327	    @Override
328	    @Transactional
329	    public String joinHousehold(Owner owner) throws DataAccessException {
330	        Collection<Owner> members = findOwnersInSameHousehold(owner.getLastName(), owner.getAddress());
331	        if (members.isEmpty()) {
332	            return null;
333	        }
334	        String householdId = members.stream()
335	            .map(Owner::getHouseholdId)
336	            .filter(Objects::nonNull)
337	            .findFirst()
338	            .orElseGet(() -> householdIdGenerator.generate(owner.getLastName(), owner.getAddress()));
339	        for (Owner member : members) {
340	            if (!householdId.equals(member.getHouseholdId())) {
341	                member.setHouseholdId(householdId);
342	                ownerRepository.save(member);
343	            }
344	        }
345	        owner.setHouseholdId(householdId);
346	        return householdId;
347	    }
