211	        return ResponseEntity.status(status).body(detail);
212	    }
213	
214	    /**
215	     * Handles {@link InvalidEmailException} raised when an owner request supplies an email
216	     * address that is not syntactically valid. Returns a 400 Bad Request whose
217	     * {@code errors} array names the {@code email} field.
218	     *
219	     * @param e The {@link InvalidEmailException} to be handled
220	     * @param request {@link HttpServletRequest} object referring to the current request.
221	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
222	     */
223	    @ExceptionHandler(InvalidEmailException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.BAD_REQUEST;
