228	        detail.setProperty("errors", List.of("email"));
229	        return ResponseEntity.status(status).body(detail);
230	    }
231	
232	    /**
233	     * Handles {@link DuplicateOwnerTelephoneException} raised when an owner request supplies a
234	     * telephone number whose normalized value is already used by an existing owner. Returns a
235	     * 409 Conflict whose {@code errors} array names the {@code telephone} field.
236	     *
237	     * @param e The {@link DuplicateOwnerTelephoneException} to be handled
238	     * @param request {@link HttpServletRequest} object referring to the current request.
239	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
240	     */
241	    @ExceptionHandler(DuplicateOwnerTelephoneException.class)
242	    @ResponseBody
243	    public ResponseEntity<ProblemDetail> handleDuplicateOwnerTelephoneException(DuplicateOwnerTelephoneException e, HttpServletRequest request) {
244	        HttpStatus status = HttpStatus.CONFLICT;
